from pathlib import Path
p=Path('/mnt/data/consciousness_lab')
engine=(p/'experiment_05_engine.js').read_text()
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0a1019"><title>Emergence Lab 05 · Beyond the Interface</title><style>
:root{color-scheme:dark;--ink:#eaf1fb;--muted:#9fb1c9;--bg:#080d16;--panel:#121c2b;--panel2:#172538;--line:#2b3d53;--mint:#78ebd0;--purple:#afa9fb;--coral:#ff9a92;--gold:#f0c874}*{box-sizing:border-box}body{background:radial-gradient(ellipse 85% 20% at 85% 0,#24394c 0,transparent 85%),var(--bg);color:var(--ink);margin:0;font:15px/1.58 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}button,select,input{font:inherit}button{cursor:pointer}a{color:var(--mint)}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--gold);outline-offset:2px}.shell{max-width:1180px;margin:0 auto;padding:23px 24px 90px}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:40px;gap:15px}.top b{letter-spacing:.16em;font-size:12px}.mark{font-size:18px;color:var(--mint);vertical-align:middle}.chip{border-radius:30px;border:1px solid #385269;background:#172737;color:#c1d4e5;padding:8px 13px;font-size:12px}.eyebrow{text-transform:uppercase;letter-spacing:.19em;font-size:11px;color:var(--mint);font-weight:800}h1{font-size:clamp(36px,5.8vw,70px);line-height:1.05;letter-spacing:-.065em;margin:10px 0 15px;max-width:1050px}h1 span{color:var(--mint)}h2{font-size:22px;letter-spacing:-.035em;margin:0}p{margin:0}.lede{max-width:875px;font-size:17px;color:var(--muted);margin:0 0 26px}.intro{border-left:3px solid var(--mint);padding-left:16px;color:#d2e3ee;max-width:860px;margin-bottom:30px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin-bottom:19px}.stat{background:#121e2e;border:1px solid var(--line);padding:16px;border-radius:15px;min-width:0}.stat .name{font-size:11px;color:var(--muted);letter-spacing:.06em;text-transform:uppercase}.stat .num{font-variant-numeric:tabular-nums;font-size:clamp(23px,3.5vw,36px);font-weight:800;letter-spacing:-.045em;margin:3px 0;white-space:nowrap}.stat .tip{font-size:11px;color:#9baec5}.panel{background:linear-gradient(155deg,#142136,#0e1825);border:1px solid var(--line);border-radius:18px;padding:24px;margin-bottom:18px}.sub{color:var(--muted);font-size:13px;max-width:850px;margin:6px 0 21px}.options{display:grid;grid-template-columns:1.4fr 1fr 1.1fr .7fr;gap:13px;align-items:end}.field{display:flex;flex-direction:column;gap:6px;min-width:0}.field label,.field .lab{color:#b9cbe0;font-size:12px;font-weight:700}.field select{background:#1b3048;border:1px solid #40556a;color:#f5f9ff;border-radius:10px;padding:11px 12px;width:100%}.field input{accent-color:var(--mint);width:100%;margin:10px 0}.field .range{font-size:12px;color:var(--mint);font-weight:750}.actions{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0 8px}.btn{border:1px solid #446079;background:#21344b;color:white;border-radius:10px;padding:11px 15px;font-weight:730}.btn.main{background:var(--mint);color:#082920;border-color:var(--mint)}.btn:hover{filter:brightness(1.13)}.btn:disabled{opacity:.42;cursor:not-allowed}.chartFrame{height:300px;margin:12px 0 8px;position:relative}canvas{width:100%;height:100%;display:block}.legend{display:flex;flex-wrap:wrap;gap:18px;color:var(--muted);font-size:12px}.key{display:inline-block;width:10px;height:10px;margin-right:5px;border-radius:3px}.note{background:#142b32;border-left:3px solid #65ccb8;border-radius:7px;padding:12px 15px;color:#c8e7e1;font-size:13px;margin-top:16px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px}.worlds{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:17px}.world{border:1px solid #3c5266;background:#182638;border-radius:13px;padding:15px;min-width:0}.worldhead{display:flex;justify-content:space-between;align-items:center;gap:8px}.iconBox{background:#3e404d;border:1px solid #7f8ca0;border-radius:9px;padding:11px 12px;font-size:19px;font-weight:850;color:#e8eaf0;margin:12px 0}.world .tag{font-size:11px;color:var(--muted)}.world .truth{font-size:14px;font-weight:750;filter:blur(5px);user-select:none}.world.revealed .truth{filter:none;user-select:auto}.world .reading{font-size:12px;color:var(--muted);min-height:36px;margin-top:7px}.world button{margin-top:12px}.mini{font-size:12px;color:var(--muted);margin-top:11px}.tablewrap{overflow:auto;margin-top:16px}table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}th,td{padding:11px 8px;border-bottom:1px solid #27374c;text-align:right;font-variant-numeric:tabular-nums}th:first-child,td:first-child{text-align:left}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.05em}td:first-child{font-weight:680}td.best{color:var(--mint);font-weight:800}.foot{font-size:12px;color:var(--muted);margin-top:13px;line-height:1.7}.pill{font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:var(--gold);font-weight:790}.listfacts{display:grid;gap:14px}.listfacts>div{border-bottom:1px solid #28394c;padding-bottom:13px}.listfacts>div:last-child{border-bottom:none;padding-bottom:0}.listfacts strong{font-size:14px}.listfacts p{color:var(--muted);font-size:13px;margin-top:4px}.bottom{font-size:12px;color:var(--muted);max-width:850px;margin-top:25px}@media(max-width:850px){.stats{grid-template-columns:repeat(2,1fr)}.options{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}.shell{padding:17px 14px 65px}.panel{padding:18px}.top{margin-bottom:26px}.chartFrame{height:260px}}@media(max-width:500px){.stat{padding:12px}.stat .num{font-size:26px}.options{grid-template-columns:1fr 1fr}.actions{display:grid;grid-template-columns:repeat(2,1fr)}.btn{padding:10px 7px;font-size:12px}.worlds{gap:7px}.world{padding:10px}.iconBox{font-size:16px;padding:8px}.world button{width:100%}h1{font-size:37px}.lede{font-size:15px}.chartFrame{height:225px}.top b{font-size:10px}.chip{font-size:10px}}
</style></head><body><main class="shell"><div class="top"><b><span class="mark">✳</span> EMERGENCE LAB / 05</b><span class="chip">Evolution × Instruments</span></div>
<header><div class="eyebrow">Can a system move beyond its senses?</div><h1>What if your senses <span>hide the truth?</span></h1><p class="lede">All agents begin with three crude symbols. Different physical conditions can look identical. Genetic mutations may create a new, costly measurement ability—and evolution decides whether that ability survives.</p><p class="intro">Unlike earlier experiments, the agents must pay to gather extra evidence. We ask whether natural selection favors discovering hidden differences, and whether that ability survives misleading information or environmental change.</p></header>
<div class="stats"><div class="stat"><div class="name">Generation</div><div id="statGen" class="num">0 / 240</div><div class="tip" id="statPhase">Initial population</div></div><div class="stat"><div class="name">Decision quality</div><div id="statQuality" class="num">—</div><div class="tip">Correctly enter safe / avoid unsafe</div></div><div class="stat"><div class="name">New sensor present</div><div id="statHardware" class="num">0%</div><div class="tip">Share carrying measurement hardware</div></div><div class="stat"><div class="name">Active measurements</div><div id="statProbe" class="num">—</div><div class="tip">Fraction of encounters probed</div></div></div>
<section class="panel" aria-label="simulation controls"><h2>Run the evolution</h2><p class="sub">200 agents × 24 encounters per generation. Each genetic lineage can evolve three action preferences, three measurement preferences, and a measurement-signal weight. All begin without measurement hardware.</p><div class="options"><div class="field"><label for="condition">Experimental condition</label><select id="condition"><option value="truthful">Informative measurement</option><option value="shuffled">Measurement is random noise</option><option value="disabled">No measurement hardware possible</option><option value="noinherit">No inheritance between generations</option></select></div><div class="field"><label for="scenario">Environment</label><select id="scenario"><option value="shift">Conditions change halfway</option><option value="stable">Conditions remain stable</option></select></div><div class="field"><label for="cost">Cost per extra measurement · <span class="range" id="costLabel">0.19</span></label><input id="cost" type="range" min="0" max="1.4" value="0.19" step="0.01"></div><div class="field"><label for="seed">World seed</label><select id="seed"><option value="41">41</option><option value="137">137</option><option value="9101">9101</option><option value="9300">9300</option></select></div></div><div class="actions"><button class="btn" id="step1">+1 generation</button><button class="btn" id="step20">+20 generations</button><button class="btn main" id="runall">Run to generation 240</button><button class="btn" id="reset">↺ Reset</button><button class="btn" id="export">↓ Export this run (CSV)</button></div><div class="chartFrame"><canvas id="chart" aria-label="History of decision quality and measurement hardware across generations" role="img"></canvas></div><div class="legend"><span><i class="key" style="background:#78ebd0"></i>Decision quality</span><span><i class="key" style="background:#afa9fb"></i>Agents with measurement hardware</span><span><i class="key" style="background:#f0c874"></i>Actual measurement use</span></div><div class="note" id="finding">Press “Run to generation 240” to watch whether measurement abilities appear and spread.</div></section>
<div class="two"><section class="panel"><h2>One icon. Two realities.</h2><p class="sub">A crude sensor reports exactly the same symbol for these two patches. An additional noisy instrument can sometimes distinguish them. Reveal the hidden properties to see what information the icon discarded.</p><div class="worlds"><div class="world" id="worldA"><div class="worldhead"><strong>Patch A</strong><span class="pill">Hidden state</span></div><div class="iconBox">◈ AMBIGUOUS</div><div class="tag">Underlying condition</div><div class="truth" aria-label="Underlying state is concealed">SAFE · Food available</div><div class="reading" id="readA">No instrument reading yet.</div><button class="btn" id="probeA">Take measurement</button><button class="btn" id="revealA">Reveal truth</button></div><div class="world" id="worldB"><div class="worldhead"><strong>Patch B</strong><span class="pill">Hidden state</span></div><div class="iconBox">◈ AMBIGUOUS</div><div class="tag">Underlying condition</div><div class="truth" aria-label="Underlying state is concealed">DANGEROUS · Toxic hazard</div><div class="reading" id="readB">No instrument reading yet.</div><button class="btn" id="probeB">Take measurement</button><button class="btn" id="revealB">Reveal truth</button></div></div><p class="mini">Illustrative fixed patches. Measurements are 92% accurate and can be wrong. They reveal information not available from the coarse icon; they don't reveal a metaphysical “ultimate reality.”</p></section>
<section class="panel"><h2>What did the simulation actually give them?</h2><p class="sub">We must distinguish genuinely selected abilities from features already supplied by the model.</p><div class="listfacts"><div><strong>Supplied by us</strong><p>A three-symbol sensor, an environment with latent safe/danger states, a mutation mechanism, costly optional measurement hardware, and seven evolvable behavioral parameters.</p></div><div><strong>Not individually programmed</strong><p>Which lineages acquire the hardware, when they choose to measure, how they use the readings, and which policies become common after many generations.</p></div><div><strong>What the experiment tests</strong><p>Whether adaptive selection can favor evidence gathering that resolves ambiguities left by a coarse sensory interface.</p></div><div><strong>What it cannot show</strong><p>That agents know their limitations, have subjective feelings, or can access an observer-independent reality. Behavioral success is not proof of consciousness.</p></div></div></section></div>
<section class="panel"><h2>Independent-seed comparison</h2><p class="sub">The table below reports 24 reproducible runs per condition, each with 240 generations. “Quality” is the fraction of decisions that matched the hidden safe/danger state, averaged over the final 30 generations.</p><div class="tablewrap"><table><thead><tr><th>Condition</th><th>Decision quality</th><th>New sensor carriers</th><th>Measurements made</th><th>Mean net payoff</th></tr></thead><tbody id="bench"></tbody></table></div><p class="foot">All conditions use the changing environment unless labeled stable. Net payoff includes energy costs. These outcomes depend on our chosen rules, costs, and mutation rates; this is an illustrative evolutionary-computation experiment, not empirical evidence about prehistoric brains.</p><div class="note">In the truthful-measurement condition, the population can evolve an ability to gather information that its original sensor throws away. In controls where the information is false, unavailable, or prohibitively expensive, that advantage disappears.</div></section><p class="bottom">Method: artificial agents, selection proportional to simulated net payoff, mutable genetic decision rules, and a stochastic extra sensor. All generations, the hidden environment, and the measurement mechanism are engineered. No consciousness criterion or experience detector is included.</p></main>
<script>__ENGINE__</script><script>
const E=window.Exp05;const $=id=>document.getElementById(id);let state;let worldR=E.rng32(883);
const benchmark=[['Informative · changing','85.7%','90.6%','85.9%','+0.454'],['Random measurements','50.8%','3.7%','1.5%','−0.067'],['No instrument allowed','50.7%','0%','0%','−0.046'],['Too expensive · 1.30','50.7%','1.4%','0.7%','−0.054'],['No inherited abilities','50.0%','1.2%','0.6%','−0.253'],['Informative · stable','89.4%','93.8%','47.8%','+0.630']];
for(const line of benchmark){let row=document.createElement('tr');line.forEach((v,i)=>{let c=document.createElement('td');c.textContent=v;if(i===1&&(line===benchmark[0]||line===benchmark[5]))c.className='best';row.append(c)});$('bench').append(row)}
function options(){return {seed:+$('seed').value,measurementCost:+$('cost').value,control:$('condition').value,scenario:$('scenario').value};}
function reset(){state=E.init(options());draw();}
function step(n){for(let i=0;i<n&&state.generation<state.options.generations;i++)E.tick(state);draw();}
function percent(x){return (100*x).toFixed(1)+'%';}
function draw(){let t=state.last;$('statGen').textContent=state.generation+' / '+state.options.generations;$('statQuality').textContent=t?percent(t.quality):'—';$('statHardware').textContent=t?percent(t.hardware):'0%';$('statProbe').textContent=t?percent(t.probes):'—';$('statPhase').textContent=t?(t.phase==='changed'?'After environmental change':'Stable physical conditions'):'Initial population';const c=$('runall');c.disabled=state.generation>=state.options.generations;$('step1').disabled=c.disabled;$('step20').disabled=c.disabled;
 const desc=$('finding');if(!t)desc.textContent='All agents start without new measurement hardware. Mutations may introduce it; selection may spread it.';else if(state.generation<20)desc.textContent='Early generations: mutations are introducing variation. A single run can be noisy; compare seeds and controls.';else if(state.options.control==='truthful'&&t.hardware>.5)desc.textContent='Measurement hardware is now present in '+percent(t.hardware)+' of agents. Their decisions match the underlying condition '+percent(t.quality)+' of the time.';else if(t.phase==='changed')desc.textContent='The world has changed: coarse icons no longer track hazards as reliably. Can agents adapt their measurement strategy?';else desc.textContent='Hardware remains uncommon. Try an informative, cheaper measurement and compare against the noise control.';
 drawChart();}
function drawChart(){const cv=$('chart'),ctx=cv.getContext('2d');const r=cv.getBoundingClientRect(),w=Math.max(300,r.width),h=Math.max(200,r.height),d=window.devicePixelRatio||1;cv.width=Math.round(w*d);cv.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);const L=43,R=15,T=13,B=30,W=w-L-R,H=h-T-B;ctx.font='11px system-ui';ctx.textAlign='right';ctx.strokeStyle='#30435a';ctx.fillStyle='#a8bdd3';ctx.lineWidth=1;
 for(let i=0;i<=4;i++){let y=T+H-H*i/4;ctx.beginPath();ctx.moveTo(L,y);ctx.lineTo(w-R,y);ctx.stroke();ctx.fillText((i*25)+'%',L-8,y+3);}
 ctx.textAlign='center';for(const g of [0,60,120,180,240]){let x=L+W*g/240;ctx.fillText(g,x,h-9);}if(state.options.scenario==='shift'){let x=L+W*.5;ctx.setLineDash([5,5]);ctx.strokeStyle='#a0aab5';ctx.beginPath();ctx.moveTo(x,T);ctx.lineTo(x,T+H);ctx.stroke();ctx.setLineDash([]);ctx.textAlign='left';ctx.fillStyle='#a0aab5';ctx.fillText('World changes',Math.min(x+5,w-104),T+13);}
 for(const [key,color] of [['quality','#78ebd0'],['hardware','#afa9fb'],['probes','#f0c874']]){ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=2.2;state.trace.forEach((t,i)=>{let x=L+W*t.generation/240,y=T+H*(1-t[key]);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();}}
function download(){let rows=['generation,phase,quality_pct,sensor_carriers_pct,measurements_pct,mean_net_payoff,probing_ambiguous,probing_safe_icon,probing_hazard_icon'];for(const t of state.trace)rows.push([t.generation,t.phase,(t.quality*100).toFixed(4),(t.hardware*100).toFixed(4),(t.probes*100).toFixed(4),t.payoff.toFixed(5),t.neutralUse.toFixed(4),t.greenUse.toFixed(4),t.redUse.toFixed(4)].join(','));let url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));let a=document.createElement('a');a.href=url;a.download='emergence_lab_05_seed_'+state.options.seed+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
$('step1').onclick=()=>step(1);$('step20').onclick=()=>step(20);$('runall').onclick=()=>step(240);$('reset').onclick=reset;$('export').onclick=download;['condition','scenario','seed'].forEach(i=>$(i).addEventListener('change',reset));$('cost').oninput=()=>{$('costLabel').textContent=(+$('cost').value).toFixed(2)};$('cost').onchange=reset;
for(const [side,safe] of [['A',true],['B',false]]){$('probe'+side).onclick=()=>{const reading=worldR()<.92?safe:!safe;$('read'+side).textContent='Instrument says: '+(reading?'LIKELY SAFE':'LIKELY DANGEROUS')+' (can be wrong)';};$('reveal'+side).onclick=()=>{$('world'+side).classList.toggle('revealed');$('reveal'+side).textContent=$('world'+side).classList.contains('revealed')?'Hide truth':'Reveal truth';};}
window.exp05Stats=()=>({generation:state.generation,hardware:state.last?.hardware||0,quality:state.last?.quality||null,trace:state.trace.length,condition:state.options.control,scenario:state.options.scenario,cost:state.options.measurementCost});window.addEventListener('resize',drawChart);reset();
</script></body></html>'''
html=html.replace('__ENGINE__',engine)
out=p/'experiment_05_beyond_the_interface.html';out.write_text(html)
print(out, len(html))
